# =============================================================================
# 03. DATA MODEL AND LOCALE-AWARE INPUT PARSING
# =============================================================================
# Screen link: "Data entry". These helpers define group tables, method-limit
# columns, blank rows, display labels, and parsing of decimal points, decimal
# commas, and local thousands separators.

safe_filename <- function(x) {
  x <- iconv(x, from = "", to = "ASCII//TRANSLIT")
  x[is.na(x)] <- "PRIDE-RL"
  x <- gsub("[^A-Za-z0-9_-]+", "_", x)
  x <- gsub("_+", "_", x)
  x <- gsub("^_|_$", "", x)
  ifelse(nchar(x) == 0L, "PRIDE-RL", x)
}

blank_group <- function(method_ids, n_rows = 3L) {
  n_rows <- max(1L, as.integer(n_rows))
  out <- data.frame(
    Analito = rep("", n_rows),
    Unidade = rep("", n_rows),
    n = rep(NA_real_, n_rows),
    Decimais = rep(3, n_rows),
    LRL_referencia = rep(NA_real_, n_rows),
    URL_referencia = rep(NA_real_, n_rows),
    stringsAsFactors = FALSE,
    check.names = FALSE
  )
  for (method_id in method_ids) {
    out[[paste0(method_id, "_LRL")]] <- NA_real_
    out[[paste0(method_id, "_URL")]] <- NA_real_
  }
  out
}

empty_row <- function(method_ids) blank_group(method_ids, 1L)

method_columns <- function(methods) {
  unlist(lapply(methods$id, function(id) c(paste0(id, "_LRL"), paste0(id, "_URL"))), use.names = FALSE)
}

display_group <- function(df, methods) {
  expected <- c(BASE_COLUMNS, method_columns(methods))
  missing <- setdiff(expected, names(df))
  for (nm in missing) df[[nm]] <- NA_real_
  df <- df[, expected, drop = FALSE]
  labels <- c(
    "Analyte", "Unit", "n", "Decimal places",
    "Comparative LRL", "Comparative URL",
    unlist(lapply(methods$label, function(x) c(paste(x, "LRL"), paste(x, "URL"))), use.names = FALSE)
  )
  names(df) <- labels
  df
}

trim_text <- function(x) trimws(as.character(x %||% ""))

is_blank <- function(x) {
  is.na(x) | trimws(as.character(x)) == ""
}

locale_decimal_mark <- function(locale = "") {
  locale <- tolower(gsub("_", "-", trimws(as.character(locale %||% "")[1L]), fixed = TRUE))
  if (!nzchar(locale)) return(NA_character_)
  language <- sub("-.*$", "", locale)
  comma_decimal_languages <- c(
    "pt", "es", "fr", "de", "it", "nl", "da", "no", "sv", "fi",
    "pl", "cs", "sk", "hu", "ro", "bg", "hr", "sl", "el", "tr",
    "ru", "uk", "id", "vi"
  )
  if (language %in% comma_decimal_languages) "," else "."
}

# Convert text pasted or typed in the browser into numeric values without
# assuming one locale. The integer mode is used for sample size and decimal
# places; other limit fields retain decimal values.
numeric_value <- function(x, locale = "", integer_expected = FALSE) {
  if (length(x) == 0L || is.null(x) || is.na(x[1L])) return(NA_real_)
  if (is.numeric(x)) return(as.numeric(x[1L]))

  value <- trimws(as.character(x[1L]))
  if (!nzchar(value)) return(NA_real_)
  value <- gsub("\u2212", "-", value, fixed = TRUE)
  value <- gsub("[[:space:]\u00A0\u202F']", "", value, perl = TRUE)

  negative_parentheses <- grepl("^\\(.*\\)$", value)
  if (negative_parentheses) value <- substring(value, 2L, nchar(value) - 1L)
  if (!grepl("^[+-]?[0-9.,]+$", value)) return(NA_real_)

  sign <- 1
  if (substr(value, 1L, 1L) == "-") sign <- -1
  value <- sub("^[+-]", "", value)
  if (!grepl("[0-9]", value) || grepl("[.,]$", value)) return(NA_real_)
  if (grepl("^[.,]", value)) value <- paste0("0", value)

  comma_count <- nchar(value) - nchar(gsub(",", "", value, fixed = TRUE))
  point_count <- nchar(value) - nchar(gsub(".", "", value, fixed = TRUE))

  normalize_decimal <- function(text, decimal_mark) {
    grouping_mark <- if (decimal_mark == ",") "." else ","
    text <- gsub(grouping_mark, "", text, fixed = TRUE)
    parts <- strsplit(text, decimal_mark, fixed = TRUE)[[1L]]
    if (length(parts) == 1L) return(parts)
    fraction <- tail(parts, 1L)
    integer <- paste(head(parts, -1L), collapse = "")
    if (!nzchar(fraction)) return(NA_character_)
    if (!nzchar(integer)) integer <- "0"
    paste0(integer, ".", fraction)
  }

  if (comma_count > 0L && point_count > 0L) {
    last_comma <- max(gregexpr(",", value, fixed = TRUE)[[1L]])
    last_point <- max(gregexpr(".", value, fixed = TRUE)[[1L]])
    normalized <- normalize_decimal(value, if (last_comma > last_point) "," else ".")
  } else if (comma_count > 0L || point_count > 0L) {
    separator <- if (comma_count > 0L) "," else "."
    parts <- strsplit(value, separator, fixed = TRUE)[[1L]]
    if (length(parts) > 2L) {
      grouping_pattern <- nzchar(parts[1L]) && all(nchar(parts[-1L]) == 3L)
      normalized <- if (grouping_pattern) {
        paste(parts, collapse = "")
      } else {
        normalize_decimal(value, separator)
      }
    } else {
      before <- parts[1L]
      after <- parts[2L]
      decimal_mark <- locale_decimal_mark(locale)
      leading_zero <- before %in% c("", "0")
      looks_grouped <- nzchar(before) && nchar(after) == 3L && !leading_zero &&
        (isTRUE(integer_expected) || (!is.na(decimal_mark) && separator != decimal_mark))
      normalized <- if (looks_grouped) paste0(before, after) else paste0(ifelse(nzchar(before), before, "0"), ".", after)
    }
  } else {
    normalized <- value
  }

  parsed <- suppressWarnings(as.numeric(normalized))
  if (!is.finite(parsed)) return(NA_real_)
  if (negative_parentheses) sign <- -1
  sign * parsed
}

format_coverage_percent <- function(coverage) {
  percentage <- 100 * as.numeric(coverage)
  label <- if (is.finite(percentage) && abs(percentage - round(percentage)) < 1e-9) {
    sprintf("%d", as.integer(round(percentage)))
  } else {
    formatC(percentage, format = "f", digits = 1L)
  }
  paste0(label, "%")
}

nonempty_rows <- function(df, methods) {
  cols <- c(setdiff(BASE_COLUMNS, "Decimais"), method_columns(methods))
  cols <- intersect(cols, names(df))
  apply(df[, cols, drop = FALSE], 1L, function(row) {
    any(!is.na(row) & trimws(as.character(row)) != "")
  })
}

# =============================================================================
# 04. INPUT VALIDATION AND PRIDE-RL CORE CALCULATIONS
# =============================================================================
# Screen link: the "Generate Analysis" button. Validation occurs before any
# analytical output or file is created. Calculation functions then feed all
# four Results subtabs, the Heatmap tab, and the HTML report.

# Check required fields, row-level consistency, permitted decimal-place values,
# comparative-limit order, available method estimates, and selected coverage.
validate_inputs <- function(groups, group_names, methods, coverage) {
  errors <- character()
  warnings <- character()

  if (nrow(methods) < 2L) {
    errors <- c(errors, "Add at least two methods to generate a comparison and ranking.")
  }
  if (!is.finite(coverage) || coverage <= 0 || coverage >= 1) {
    errors <- c(errors, "The coverage probability must be greater than 0 and less than 1.")
  }

  complete_methods_global <- setNames(integer(nrow(methods)), methods$id)
  valid_rows <- 0L

  for (group_id in names(groups)) {
    df <- groups[[group_id]]
    keep <- nonempty_rows(df, methods)
    df <- df[keep, , drop = FALSE]
    group_label <- group_names[[group_id]] %||% group_id

    if (nrow(df) == 0L) {
      warnings <- c(warnings, sprintf("Group '%s' is empty and will be ignored.", group_label))
      next
    }

    for (i in seq_len(nrow(df))) {
      prefix <- sprintf("Group '%s', row %d", group_label, i)
      analyte <- trimws(as.character(df$Analito[i]))
      n_value <- numeric_value(df$n[i])
      unit <- trimws(as.character(df$Unidade[i]))
      decimals <- numeric_value(df$Decimais[i])
      ref_lrl <- numeric_value(df$LRL_referencia[i])
      ref_url <- numeric_value(df$URL_referencia[i])

      if (analyte == "") errors <- c(errors, paste0(prefix, ": enter the analyte/test name."))
      if (!is.finite(n_value) || n_value <= 0 || n_value != floor(n_value)) {
        errors <- c(errors, paste0(prefix, ": n must be a positive integer."))
      }
      if (unit == "") errors <- c(errors, paste0(prefix, ": enter the unit of measurement."))
      if (!is.finite(decimals) || decimals < 0 || decimals > 8 || decimals != floor(decimals)) {
        errors <- c(errors, paste0(prefix, ": decimal places must be an integer from 0 to 8."))
      }
      if (!is.finite(ref_lrl) || ref_lrl < 0) {
        errors <- c(errors, paste0(prefix, ": the comparative LRL must be numeric and greater than or equal to zero."))
      }
      if (!is.finite(ref_url) || ref_url <= 0) {
        errors <- c(errors, paste0(prefix, ": the comparative URL must be numeric and greater than zero."))
      }
      if (is.finite(ref_lrl) && is.finite(ref_url) && ref_url <= ref_lrl) {
        errors <- c(errors, paste0(prefix, ": the comparative URL must be greater than the comparative LRL."))
      }

      complete_here <- 0L
      for (j in seq_len(nrow(methods))) {
        id <- methods$id[j]
        lrl <- numeric_value(df[[paste0(id, "_LRL")]][i])
        url <- numeric_value(df[[paste0(id, "_URL")]][i])
        label <- methods$label[j]
        one_missing <- xor(is.na(lrl), is.na(url))
        if (one_missing) {
          errors <- c(errors, sprintf("%s: enter both the LRL and URL for method '%s', or leave both blank.", prefix, label))
        }
        if (!is.na(lrl) && !is.na(url)) {
          if (!is.finite(lrl) || !is.finite(url)) {
            errors <- c(errors, sprintf("%s: the limits for method '%s' must be numeric.", prefix, label))
          } else if (url <= lrl) {
            errors <- c(errors, sprintf("%s: for method '%s', the URL must be greater than the LRL.", prefix, label))
          } else {
            complete_here <- complete_here + 1L
            complete_methods_global[id] <- complete_methods_global[id] + 1L
          }
        }
      }
      if (complete_here < 2L) {
        errors <- c(errors, paste0(prefix, ": enter complete LRL/URL pairs for at least two methods."))
      }
      valid_rows <- valid_rows + 1L
    }
  }

  if (valid_rows == 0L) errors <- c(errors, "Enter at least one valid analyte.")
  if (sum(complete_methods_global > 0L) < 2L) {
    errors <- c(errors, "At least two methods must have complete limits for the ranking to be calculated.")
  }

  list(errors = unique(errors), warnings = unique(warnings))
}

# Calculate the permissible-uncertainty parameters separately for each
# comparative LRL and URL. The returned pD values define the half-width of the
# two equivalence intervals used to standardize method deviations.
calculate_reference_row <- function(ref_lrl, ref_url, decimals, z_value) {
  lower_for_log <- if (ref_lrl == 0) 0.15 * ref_url else ref_lrl
  cve <- sqrt(exp(((log(ref_url) - log(lower_for_log)) / 3.92)^2) - 1)
  pcva_term <- cve * 100 - 0.25
  if (!is.finite(pcva_term) || pcva_term <= 0) {
    stop("The comparative interval is too narrow to calculate pCVA using the original formula.", call. = FALSE)
  }
  pcva <- sqrt(pcva_term) / 100
  medln <- exp((log(lower_for_log) + log(ref_url)) / 2)
  psda_med <- pcva * medln
  slope <- (psda_med - 0.2 * psda_med) / medln
  intercept <- 0.2 * psda_med
  psda_lrl <- ref_lrl * slope + intercept
  pd_lrl <- z_value * psda_lrl
  psda_url <- ref_url * slope + intercept
  pd_url <- z_value * psda_url

  c(
    CVE = cve,
    pCVA = pcva,
    Medln = medln,
    pSDA_Med = psda_med,
    Slope = slope,
    Intercept = intercept,
    pSDA_LRL = psda_lrl,
    pD_LRL = pd_lrl,
    EI_LRL_inferior = ref_lrl - pd_lrl,
    EI_LRL_superior = ref_lrl + pd_lrl,
    pSDA_URL = psda_url,
    pD_URL = pd_url,
    EI_URL_inferior = ref_url - pd_url,
    EI_URL_superior = ref_url + pd_url
  )
}

rank_eq_desc <- function(x) {
  ifelse(is.na(x), NA_integer_, rank(-x, ties.method = "min", na.last = "keep"))
}

# Direct ranking displayed in Results > Inclusion ranking. It counts limits
# meeting the inclusive equivalence criterion |D_RL| <= 1.
simple_ranking <- function(detail, methods, scope_col = "Grupo") {
  scopes <- unique(detail[[scope_col]])
  pieces <- list()
  index <- 1L
  for (scope in scopes) {
    current <- detail[detail[[scope_col]] == scope, , drop = FALSE]
    rows <- lapply(seq_len(nrow(methods)), function(j) {
      label <- methods$label[j]
      d <- current[current$Metodo == label, , drop = FALSE]
      lrl_valid <- !is.na(d$Dentro_EI_LRL)
      url_valid <- !is.na(d$Dentro_EI_URL)
      lrl_n <- sum(lrl_valid)
      url_n <- sum(url_valid)
      lrl_yes <- sum(d$Dentro_EI_LRL[lrl_valid])
      url_yes <- sum(d$Dentro_EI_URL[url_valid])
      total <- lrl_n + url_n
      data.frame(
        Escopo = scope,
        Metodo = label,
        Percentual_RLs_no_EI = if (total > 0L) (lrl_yes + url_yes) / total else NA_real_,
        LRLs_no_EI = lrl_yes,
        Total_LRLs = lrl_n,
        URLs_no_EI = url_yes,
        Total_URLs = url_n,
        Total_no_EI = lrl_yes + url_yes,
        Total_possivel = total,
        stringsAsFactors = FALSE
      )
    })
    tab <- do.call(rbind, rows)
    tab <- tab[!is.na(tab$Percentual_RLs_no_EI), , drop = FALSE]
    tab$Rank <- rank_eq_desc(tab$Percentual_RLs_no_EI)
    tab <- tab[order(tab$Rank, -tab$Percentual_RLs_no_EI, tab$Metodo), , drop = FALSE]
    pieces[[index]] <- tab[, c("Escopo", "Rank", "Metodo", "Percentual_RLs_no_EI", "LRLs_no_EI", "Total_LRLs", "URLs_no_EI", "Total_URLs", "Total_no_EI", "Total_possivel")]
    index <- index + 1L
  }
  do.call(rbind, pieces)
}

# Multidimensional ranking displayed in Results > Composite ranking.
# d1 measures conformity, d2 proximity, d3 tail behaviour, and d4 severity;
# their equally weighted geometric mean is the PRIDe-RL score.
composite_ranking <- function(heatmap_long, methods) {
  scopes <- c(sort(unique(heatmap_long$Grupo)), "Global")
  pieces <- list()
  index <- 1L

  for (scope in scopes) {
    current <- if (scope == "Global") heatmap_long else heatmap_long[heatmap_long$Grupo == scope, , drop = FALSE]
    rows <- lapply(seq_len(nrow(methods)), function(j) {
      label <- methods$label[j]
      d <- current$d[current$Metodo == label]
      d <- d[is.finite(d)]
      n_limits <- length(d)
      if (n_limits == 0L) return(NULL)
      abs_d <- abs(d)
      conformity_n <- sum(abs_d <= 1)
      d1 <- conformity_n / n_limits
      mean_abs <- mean(abs_d)
      d2 <- 1 / (1 + mean_abs)
      p90 <- as.numeric(stats::quantile(abs_d, probs = 0.90, type = 7, names = FALSE))
      d3 <- 1 / (1 + max(0, p90 - 1))
      severe_n <- sum(abs_d > 2)
      d4 <- 1 / (1 + 5 * severe_n / n_limits)
      score <- (d1 * d2 * d3 * d4)^(1 / 4)
      data.frame(
        Escopo = scope,
        Metodo = label,
        N_limites = n_limits,
        Conformidade_n = conformity_n,
        d1_Conformidade = d1,
        Media_abs_D_RL = mean_abs,
        d2_Proximidade = d2,
        P90_abs_D_RL = p90,
        d3_Cauda = d3,
        Severidade_n = severe_n,
        d4_Severidade = d4,
        PRIDE_RL_score = score,
        stringsAsFactors = FALSE
      )
    })
    tab <- do.call(rbind, rows)
    if (is.null(tab) || nrow(tab) == 0L) next
    tab$Rank <- rank_eq_desc(tab$PRIDE_RL_score)
    # Equivalent to RANK.EQ plus progressive COUNTIF: preserves tied Rank values
    # and creates a unique position based on the original registration order.
    tab$Posicao <- vapply(seq_len(nrow(tab)), function(i) {
      tab$Rank[i] + sum(tab$PRIDE_RL_score[seq_len(i)] == tab$PRIDE_RL_score[i]) - 1L
    }, numeric(1))
    tab <- tab[order(tab$Posicao), , drop = FALSE]
    pieces[[index]] <- tab[, c(
      "Escopo", "Posicao", "Rank", "Metodo", "N_limites", "Conformidade_n", "d1_Conformidade",
      "Media_abs_D_RL", "d2_Proximidade", "P90_abs_D_RL", "d3_Cauda",
      "Severidade_n", "d4_Severidade", "PRIDE_RL_score"
    )]
    index <- index + 1L
  }
  do.call(rbind, pieces)
}

# Main analytical orchestrator. It applies the selected central coverage,
# calculates row-level equivalence intervals and D-RL values, and returns one
# result bundle reused by every result screen and exported artifact.
calculate_all <- function(groups, group_names, methods, coverage) {
  alpha <- 1 - coverage
  quantile_order <- 1 - alpha / 2
  z_value <- stats::qnorm(quantile_order)
  calculation_rows <- list()
  detail_rows <- list()
  heat_rows <- list()
  row_index <- 1L
  detail_index <- 1L
  heat_index <- 1L

  for (group_id in names(groups)) {
    df <- groups[[group_id]]
    df <- df[nonempty_rows(df, methods), , drop = FALSE]
    if (nrow(df) == 0L) next
    group_label <- group_names[[group_id]] %||% group_id

    for (i in seq_len(nrow(df))) {
      analyte <- trimws(as.character(df$Analito[i]))
      n_value <- as.integer(df$n[i])
      unit <- trimws(as.character(df$Unidade[i]))
      decimals <- as.integer(df$Decimais[i])
      ref_lrl <- as.numeric(df$LRL_referencia[i])
      ref_url <- as.numeric(df$URL_referencia[i])
      ref_calc <- calculate_reference_row(ref_lrl, ref_url, decimals, z_value)

      calculation_rows[[row_index]] <- data.frame(
        Grupo = group_label,
        Registro = i,
        Analito = analyte,
        n = n_value,
        Unidade = unit,
        Decimais = decimals,
        LRL_referencia = ref_lrl,
        URL_referencia = ref_url,
        as.list(ref_calc),
        EI_LRL = paste(
          formatC(ref_calc[["EI_LRL_inferior"]], format = "f", digits = decimals),
          "to",
          formatC(ref_calc[["EI_LRL_superior"]], format = "f", digits = decimals)
        ),
        EI_URL = paste(
          formatC(ref_calc[["EI_URL_inferior"]], format = "f", digits = decimals),
          "to",
          formatC(ref_calc[["EI_URL_superior"]], format = "f", digits = decimals)
        ),
        stringsAsFactors = FALSE,
        check.names = FALSE
      )
      row_index <- row_index + 1L

      for (j in seq_len(nrow(methods))) {
        id <- methods$id[j]
        method_label <- methods$label[j]
        est_lrl <- as.numeric(df[[paste0(id, "_LRL")]][i])
        est_url <- as.numeric(df[[paste0(id, "_URL")]][i])
        if (is.na(est_lrl) && is.na(est_url)) next
        d_lrl <- (est_lrl - ref_lrl) / ref_calc[["pD_LRL"]]
        d_url <- (est_url - ref_url) / ref_calc[["pD_URL"]]
        inside_lrl <- as.integer(est_lrl >= ref_calc[["EI_LRL_inferior"]] && est_lrl <= ref_calc[["EI_LRL_superior"]])
        inside_url <- as.integer(est_url >= ref_calc[["EI_URL_inferior"]] && est_url <= ref_calc[["EI_URL_superior"]])

        detail_rows[[detail_index]] <- data.frame(
          Grupo = group_label,
          Registro = i,
          Analito = analyte,
          n = n_value,
          Unidade = unit,
          Metodo = method_label,
          LRL_estimado = est_lrl,
          D_RL_LRL = d_lrl,
          Dentro_EI_LRL = inside_lrl,
          URL_estimado = est_url,
          D_RL_URL = d_url,
          Dentro_EI_URL = inside_url,
          stringsAsFactors = FALSE
        )
        detail_index <- detail_index + 1L

        heat_rows[[heat_index]] <- data.frame(
          Grupo = group_label,
          Registro = i,
          Analito = analyte,
          n = n_value,
          Unidade = unit,
          Limite = "LRL",
          Metodo = method_label,
          d = d_lrl,
          stringsAsFactors = FALSE
        )
        heat_index <- heat_index + 1L
        heat_rows[[heat_index]] <- data.frame(
          Grupo = group_label,
          Registro = i,
          Analito = analyte,
          n = n_value,
          Unidade = unit,
          Limite = "URL",
          Metodo = method_label,
          d = d_url,
          stringsAsFactors = FALSE
        )
        heat_index <- heat_index + 1L
      }
    }
  }

  calculations <- do.call(rbind, calculation_rows)
  detail <- do.call(rbind, detail_rows)
  heatmap_long <- do.call(rbind, heat_rows)

  simple_group <- simple_ranking(detail, methods, "Grupo")
  global_detail <- detail
  global_detail$Global <- "Global"
  simple_global <- simple_ranking(global_detail, methods, "Global")
  simple <- rbind(simple_group, simple_global)
  composite <- composite_ranking(heatmap_long, methods)

  list(
    coverage = coverage,
    alpha = alpha,
    quantile_order = quantile_order,
    z_value = z_value,
    calculations = calculations,
    detail = detail,
    heatmap = heatmap_long,
    simple_ranking = simple,
    composite_ranking = composite
  )
}

# =============================================================================
# 05. HEATMAP PREPARATION, LAYOUT, DRAWING, AND EXPORT
# =============================================================================
# Screen link: "Heatmap". The same scientific figure is also embedded in the
# generated HTML report and exported separately at 600 dpi.

# Map D-RL values to the green-yellow-red visual scale used by PRIDe-RL.
heat_color <- function(value) {
  if (!is.finite(value)) return("#F1F3F5")
  anchors <- grDevices::colorRamp(c("#63BE7B", "#FFEB84", "#F8696B"), space = "Lab")
  position <- min(abs(value), 2) / 2
  rgb <- anchors(position)
  grDevices::rgb(rgb[1], rgb[2], rgb[3], maxColorValue = 255)
}

heatmap_matrix <- function(heatmap_long, methods) {
  key_cols <- c("Grupo", "Registro", "Analito", "n", "Unidade", "Limite")
  keys <- unique(heatmap_long[, key_cols, drop = FALSE])
  keys$order_group <- match(keys$Grupo, unique(heatmap_long$Grupo))
  keys$order_analyte <- ave(seq_len(nrow(keys)), keys$Grupo, FUN = seq_along)
  keys$order_limit <- match(keys$Limite, c("LRL", "URL"))
  keys <- keys[order(keys$order_group, keys$order_analyte, keys$order_limit), , drop = FALSE]
  matrix_values <- matrix(NA_real_, nrow = nrow(keys), ncol = nrow(methods))
  colnames(matrix_values) <- methods$label

  for (i in seq_len(nrow(keys))) {
    for (j in seq_len(nrow(methods))) {
      hit <- heatmap_long$Grupo == keys$Grupo[i] &
        heatmap_long$Registro == keys$Registro[i] &
        heatmap_long$Analito == keys$Analito[i] &
        heatmap_long$n == keys$n[i] &
        heatmap_long$Unidade == keys$Unidade[i] &
        heatmap_long$Limite == keys$Limite[i] &
        heatmap_long$Metodo == methods$label[j]
      if (any(hit)) matrix_values[i, j] <- heatmap_long$d[which(hit)[1]]
    }
  }
  list(keys = keys, matrix = matrix_values)
}

heatmap_layout <- function(keys, matrix_values) {
  max_chars <- function(x, minimum = 1L) {
    values <- nchar(as.character(x), type = "width", allowNA = TRUE, keepNA = FALSE)
    values <- values[!is.na(values)]
    if (length(values) == 0L) return(minimum)
    max(minimum, max(values))
  }

  fitted_width <- function(header, values, minimum, character_width = 0.060, padding = 0.16) {
    max(minimum, padding + character_width * max_chars(c(header, values)))
  }

  n_labels <- format(keys$n, scientific = FALSE, trim = TRUE)
  formatted_values <- ifelse(
    is.finite(matrix_values),
    formatC(matrix_values, format = "f", digits = 2),
    "—"
  )
  method_width <- fitted_width(
    colnames(matrix_values),
    as.vector(formatted_values),
    minimum = 0.64,
    character_width = 0.065,
    padding = 0.20
  )

  widths <- c(
    Group = fitted_width("Group", character(), minimum = 0.42),
    `Analyte/Test` = fitted_width("Analyte/Test", keys$Analito, minimum = 0.72),
    Unit = fitted_width("Unit", keys$Unidade, minimum = 0.52),
    n = fitted_width("n", n_labels, minimum = 0.40),
    RL = fitted_width("RL", keys$Limite, minimum = 0.40)
  )
  boundaries <- c(0, cumsum(widths))
  list(
    widths = widths,
    boundaries = boundaries,
    annotation_width = sum(widths),
    method_width = method_width,
    total_width = sum(widths) + ncol(matrix_values) * method_width
  )
}

heatmap_font_sizes <- function(row_count, method_count) {
  row_factor <- sqrt(32 / max(32, row_count))
  column_factor <- sqrt(10 / max(10, method_count))
  density_factor <- min(row_factor, column_factor)
  list(
    body = max(0.62, min(0.80, 0.80 * density_factor)),
    value = max(0.62, min(0.82, 0.82 * density_factor)),
    header = max(0.68, min(0.80, 0.80 * column_factor))
  )
}

heatmap_dimensions <- function(row_count) {
  row_inches <- if (row_count <= 20L) {
    0.25
  } else if (row_count <= 50L) {
    0.22
  } else if (row_count <= 90L) {
    0.20
  } else {
    0.19
  }
  row_pixels <- round(row_inches * 100)

  list(
    row_inches = row_inches,
    row_pixels = row_pixels,
    png_height = min(32, max(1.9, 0.68 + row_inches * row_count)),
    screen_height = min(3000, max(240, 62 + row_pixels * row_count))
  )
}

# Draw the full heatmap with merged group cells, descriptive columns, method
# columns, formatted D-RL values, and visual emphasis outside equivalence.
draw_heatmap <- function(heatmap_long, methods) {
  prepared <- heatmap_matrix(heatmap_long, methods)
  keys <- prepared$keys
  mat <- prepared$matrix
  nr <- nrow(mat)
  nc <- ncol(mat)
  if (nr == 0L || nc == 0L) return(invisible(NULL))

  layout <- heatmap_layout(keys, mat)
  bounds <- layout$boundaries
  matrix_start <- layout$annotation_width
  method_width <- layout$method_width
  total_width <- layout$total_width
  font_sizes <- heatmap_font_sizes(nr, nc)
  body_cex <- font_sizes$body
  value_cex <- font_sizes$value
  header_cex <- font_sizes$header
  header_labels <- c(names(layout$widths), colnames(mat))
  header_positions <- c(
    (bounds[-length(bounds)] + bounds[-1L]) / 2,
    matrix_start + (seq_len(nc) - 0.5) * method_width
  )
  top_margin <- 1.65

  old_par <- graphics::par(no.readonly = TRUE)
  on.exit(graphics::par(old_par), add = TRUE)
  graphics::par(
    mar = c(0.65, 0.55, top_margin, 0.55),
    mgp = c(1.5, 0.22, 0),
    xpd = NA,
    family = "sans",
    fg = "#000000",
    col = "#000000",
    col.axis = "#000000"
  )
  graphics::plot.new()
  graphics::plot.window(xlim = c(0, total_width), ylim = c(nr, 0), xaxs = "i", yaxs = "i")

  for (i in seq_len(nr)) {
    row_fill <- if (i %% 2L == 0L) "#F7F9FA" else "#FFFFFF"
    for (column in 2:5) {
      graphics::rect(bounds[column], i - 1, bounds[column + 1L], i, col = row_fill, border = "#DCE4E6", lwd = 0.65)
    }
    graphics::text((bounds[2] + bounds[3]) / 2, i - 0.5, keys$Analito[i], cex = body_cex, col = "#000000")
    graphics::text((bounds[3] + bounds[4]) / 2, i - 0.5, keys$Unidade[i], cex = body_cex, col = "#000000")
    graphics::text((bounds[4] + bounds[5]) / 2, i - 0.5, format(keys$n[i], scientific = FALSE, trim = TRUE), cex = body_cex, col = "#000000")
    graphics::text((bounds[5] + bounds[6]) / 2, i - 0.5, keys$Limite[i], cex = body_cex, font = 2, col = "#000000")
  }

  for (i in seq_len(nr)) {
    for (j in seq_len(nc)) {
      value <- mat[i, j]
      x_left <- matrix_start + (j - 1) * method_width
      graphics::rect(x_left, i - 1, x_left + method_width, i, col = heat_color(value), border = "white", lwd = 0.8)
      label <- if (is.finite(value)) formatC(value, format = "f", digits = 2) else "—"
      graphics::text(x_left + method_width / 2, i - 0.5, label, cex = value_cex, font = if (is.finite(value) && abs(value) > 1) 2 else 1, col = "#000000")
    }
  }

  group_runs <- rle(as.character(keys$Grupo))
  group_ends <- cumsum(group_runs$lengths)
  group_starts <- c(1L, head(group_ends, -1L) + 1L)
  for (g in seq_along(group_runs$values)) {
    y_top <- group_starts[g] - 1
    y_bottom <- group_ends[g]
    group_cex <- min(0.88, body_cex * 1.10)
    graphics::rect(bounds[1], y_top, bounds[2], y_bottom, col = "#000000", border = "#000000", lwd = 0.9)
    graphics::text(
      (bounds[1] + bounds[2]) / 2,
      (y_top + y_bottom) / 2,
      group_runs$values[g],
      srt = 90,
      cex = group_cex,
      font = 2,
      col = "#FFFFFF"
    )
  }

  graphics::axis(3, at = header_positions, labels = header_labels, las = 1, tick = FALSE, cex.axis = header_cex, font.axis = 2, col.axis = "#000000", line = 0.05)

  if (nr > 1L) {
    analyte_change <- which(keys$Registro[-1L] != keys$Registro[-nr] | keys$Grupo[-1L] != keys$Grupo[-nr])
    if (length(analyte_change) > 0L) {
      graphics::segments(bounds[2], analyte_change, total_width, analyte_change, col = "#BCCACC", lwd = 0.7)
    }
  }
  if (length(group_ends) > 1L) {
    graphics::segments(0, head(group_ends, -1L), total_width, head(group_ends, -1L), col = "#334B52", lwd = 1.35)
  }

  graphics::segments(matrix_start, 0, matrix_start, nr, col = "#6F858A", lwd = 1.15)
  graphics::rect(0, 0, total_width, nr, border = "#AFC0C4", lwd = 0.9)
  invisible(prepared)
}

# Export the same heatmap drawing used on screen. The default 600 dpi output is
# saved under 1_Outputs/Figures after Generate Analysis is clicked.
save_heatmap_png <- function(path, heatmap_long, methods, dpi = 600) {
  prepared <- heatmap_matrix(heatmap_long, methods)
  nr <- nrow(prepared$matrix)
  nc <- ncol(prepared$matrix)
  layout <- heatmap_layout(prepared$keys, prepared$matrix)
  dimensions <- heatmap_dimensions(nr)
  width_in <- min(30, max(7.0, 1.12 * layout$total_width))
  height_in <- dimensions$png_height
  dir.create(dirname(path), recursive = TRUE, showWarnings = FALSE)
  png_args <- list(filename = path, width = width_in, height = height_in, units = "in", res = dpi)
  if (isTRUE(capabilities("cairo"))) png_args$type <- "cairo-png"
  do.call(grDevices::png, png_args)
  on.exit(grDevices::dev.off(), add = TRUE)
  draw_heatmap(heatmap_long, methods)
  invisible(path)
}

# =============================================================================
# 06. REFERENCES, FORMULAS, AND RESULT-TABLE PRESENTATION HELPERS
# =============================================================================
# Screen links:
# - "References": methodological_references_ui().
# - "PRIDe-RL scoring framework": MathJax formula and variable helpers.
# - "Results": labels, numeric formatting, kableExtra tables, grouped headers,
#   PRIDe-RL score colors, and group/global ranking tables.

html_escape <- function(x) {
  x <- as.character(x)
  x <- gsub("&", "&amp;", x, fixed = TRUE)
  x <- gsub("<", "&lt;", x, fixed = TRUE)
  x <- gsub(">", "&gt;", x, fixed = TRUE)
  x <- gsub('"', "&quot;", x, fixed = TRUE)
  x
}

# Render the centralized bibliography as accessible clickable DOI links in the
# References tab.
methodological_references_ui <- function() {
  tags$ol(
    class = "methodology-reference-list",
    lapply(METHODOLOGICAL_REFERENCES, function(reference) {
      tags$li(
        tags$span(reference$authors, ", ", reference$title, ", "),
        tags$em(reference$journal),
        tags$span(" ", reference$publication, " "),
        tags$a(
          class = "doi-link",
          href = reference$doi,
          target = "_blank",
          rel = "noopener noreferrer",
          `aria-label` = "Open DOI in a new browser tab",
          reference$doi
        )
      )
    })
  )
}

methodological_references_report_html <- function() {
  items <- vapply(METHODOLOGICAL_REFERENCES, function(reference) {
    paste0(
      "<li>",
      html_escape(reference$authors), ", ", html_escape(reference$title), ", ",
      "<i>", html_escape(reference$journal), "</i> ",
      html_escape(reference$publication), " ",
      "<a class='doi-link' href='", html_escape(reference$doi),
      "' target='_blank' rel='noopener noreferrer' aria-label='Open DOI in a new browser tab'>",
      html_escape(reference$doi), "</a></li>"
    )
  }, character(1))
  paste0("<ol class='methodology-reference-list'>", paste0(items, collapse = ""), "</ol>")
}

# Wrap LaTeX expressions for MathJax rendering in the scoring-framework tab.
methodology_formula_ui <- function(latex, aria_label, modifier_class = NULL) {
  formula_classes <- paste(
    c("methodology-formula", modifier_class),
    collapse = " "
  )

  div(
    class = formula_classes,
    role = "math",
    `aria-label` = aria_label,
    HTML(paste0("$$\n\\Large{\n", latex, "\n}\n$$"))
  )
}

methodology_variable_ui <- function(latex, description) {
  div(
    class = "methodology-variable-row",
    span(class = "methodology-variable-symbol", HTML(paste0("\\(", latex, "\\)"))),
    span(class = "methodology-variable-separator", ", "),
    span(class = "methodology-variable-description", description)
  )
}

methodology_where_ui <- function(...) {
  div(
    class = "methodology-where",
    p(class = "methodology-where-title", "Where:"),
    ...
  )
}

# Render the compact variable glossary displayed immediately below the workflow
# figure. HTML subscripts and superscripts keep the notation readable without
# adding the visual weight of the larger MathJax formula blocks.
methodology_figure_variable_ui <- function(symbol_html, description) {
  div(
    class = "methodology-figure-variable-row",
    span(class = "methodology-figure-variable-symbol", HTML(symbol_html)),
    span(class = "methodology-figure-variable-separator", ", "),
    span(class = "methodology-figure-variable-description", description)
  )
}

# Build the scoring-framework content used by the portable HTML report. The
# workflow figure is the same high-resolution Base64 asset shown in the Shiny
# tab, and the equations and definitions reproduce the same methodological
# content without requiring an external MathJax or image file.
methodology_report_variable_row <- function(symbol_html, description) {
  paste0(
    "<div class='methodology-variable-row'><span class='methodology-variable-symbol'>",
    symbol_html,
    "</span><span class='methodology-variable-separator'>, </span>",
    "<span class='methodology-variable-description'>", html_escape(description), "</span></div>"
  )
}

methodology_report_where <- function(rows) {
  paste0(
    "<div class='methodology-where'><p class='methodology-where-title'>Where:</p>",
    paste0(rows, collapse = ""),
    "</div>"
  )
}

methodology_report_formula <- function(mathml, aria_label, score = FALSE) {
  paste0(
    "<div class='methodology-formula", if (score) " methodology-score-formula" else "",
    "' role='math' aria-label='", html_escape(aria_label), "'>",
    "<math xmlns='http://www.w3.org/1998/Math/MathML' display='block'>", mathml, "</math></div>"
  )
}

methodology_framework_report_html <- function() {
  figure_variables <- list(
    c("LRL", "lower reference limit."),
    c("URL", "upper reference limit."),
    c("CV<sub>E</sub><sup>*</sup>", "empirical biological variation coefficient derived on the logarithmic scale from the reference interval. If the LRL is unknown, it is set at 15% of the URL for the CVE calculation."),
    c("pCV<sub>A</sub>", "permissible analytical coefficient of variation (CVA) at the median on the linear scale, obtained from the CVE."),
    c("Med<sub>ln</sub>", "median of the reference interval on the logarithmic scale."),
    c("pSD<sub>A,Med</sub>", "permissible analytical standard deviation (SDA) at the median of the reference interval."),
    c("Slope", "calculated from pSDA,Med and the median of the reference interval."),
    c("Intercept", "related to the limit of detection. Because the limit of detection is usually unknown for the human material matrix, 20% of pSDA,Med is applied empirically here as a surrogate."),
    c("pSD<sub>A,LRL</sub>", "permissible analytical standard deviation at the lower reference limit."),
    c("pSD<sub>A,URL</sub>", "permissible analytical standard deviation at the upper reference limit."),
    c("pD<sub>LRL</sub>", "permissible difference (pD) for the LRL, based on Haeckel's approach, which estimates the CVE from the reference interval provided by the user."),
    c("pD<sub>URL</sub>", "permissible difference (pD) for the URL, based on Haeckel's approach, which estimates the CVE from the reference interval provided by the user."),
    c("EI", "equivalence interval, the range around a reference limit within which an estimate of that same limit obtained by another approach is considered equivalent."),
    c("EI<sub>LRL</sub>", "equivalence interval of the lower reference limit (LRL ± pDLRL)."),
    c("EI<sub>URL</sub>", "equivalence interval of the upper reference limit (URL ± pDURL)."),
    c("RL", "reference limit, either the lower (LRL) or the upper (URL) reference limit.")
  )
  figure_rows <- vapply(figure_variables, function(item) {
    methodology_report_variable_row(item[[1]], item[[2]])
  }, character(1))

  d1_math <- paste0(
    "<msub><mi>d</mi><mn>1</mn></msub><mo>=</mo><mfrac><mrow><mi>n</mi><mo>(</mo>",
    "<mo>|</mo><msub><mi>D</mi><mi>RL</mi></msub><mo>|</mo><mo>≤</mo><mn>1</mn><mo>)</mo></mrow><mi>N</mi></mfrac>"
  )
  d2_math <- paste0(
    "<msub><mi>d</mi><mn>2</mn></msub><mo>=</mo><mfrac><mn>1</mn><mrow><mn>1</mn><mo>+</mo>",
    "<mi>mean</mi><mo>(</mo><mo>|</mo><msub><mi>D</mi><mi>RL</mi></msub><mo>|</mo><mo>)</mo></mrow></mfrac>"
  )
  d3_math <- paste0(
    "<msub><mi>d</mi><mn>3</mn></msub><mo>=</mo><mfrac><mn>1</mn><mrow><mn>1</mn><mo>+</mo><mi>max</mi><mo>[</mo>",
    "<mn>0</mn><mo>,</mo><msub><mi>P</mi><mn>90</mn></msub><mo>(</mo><mo>|</mo><msub><mi>D</mi><mi>RL</mi></msub>",
    "<mo>|</mo><mo>)</mo><mo>−</mo><mn>1</mn><mo>]</mo></mrow></mfrac>"
  )
  d4_math <- paste0(
    "<msub><mi>d</mi><mn>4</mn></msub><mo>=</mo><mfrac><mn>1</mn><mrow><mn>1</mn><mo>+</mo><mn>5</mn><mo>×</mo>",
    "<mfrac><mrow><mi>n</mi><mo>(</mo><mo>|</mo><msub><mi>D</mi><mi>RL</mi></msub><mo>|</mo><mo>&gt;</mo><mn>2</mn><mo>)</mo></mrow><mi>N</mi></mfrac></mrow></mfrac>"
  )
  score_math <- paste0(
    "<mrow><mi mathvariant='bold-italic'>PRIDe Score</mi><mo>=</mo><mroot><mrow>",
    "<msub><mi>d</mi><mn>1</mn></msub><mo>×</mo><msub><mi>d</mi><mn>2</mn></msub><mo>×</mo>",
    "<msub><mi>d</mi><mn>3</mn></msub><mo>×</mo><msub><mi>d</mi><mn>4</mn></msub></mrow><mn>4</mn></mroot></mrow>"
  )

  paste0(
    "<figure class='methodology-overview-figure'>",
    "<img src='", PRIDE_FRAMEWORK_FIGURE_DATA_URI, "' alt='PRIDe-RL workflow from comparative reference limits through the equivalence intervals, D-RL index, heatmap, and four-dimensional PRIDe-RL score.'>",
    "<figcaption>Overview of the PRIDe-RL calculation workflow. The coverage factor is represented by the standard-normal quantile <i>z</i> at probability (1 + <i>P</i>) / 2, where <i>P</i> is the nominal central coverage selected by the user. The equations for the four scoring dimensions are detailed below.</figcaption>",
    "</figure>",
    "<div class='methodology-figure-abbreviations' aria-label='Abbreviations and variable definitions for the PRIDe-RL workflow figure'>",
    "<p class='methodology-figure-abbreviations-title'>Abbreviations:</p>",
    "<div class='methodology-figure-abbreviations-list'>", paste0(figure_rows, collapse = ""), "</div></div>",
    "<ul class='methodology-dimension-list'>",
    "<li><strong>Direct ranking</strong><p>Proportion of LRLs and URLs within their respective equivalence intervals.</p></li>",
    "<li><strong>d1 — Conformity</strong>", methodology_report_formula(d1_math, "d one equals the number of absolute D R L values less than or equal to one, divided by N."),
    methodology_report_where(c(
      methodology_report_variable_row("n(|D<sub>RL</sub>| ≤ 1)", "number of evaluated reference-limit estimates (LRLs and URLs) whose absolute deviation index is less than or equal to 1, indicating inclusion within the equivalence interval."),
      methodology_report_variable_row("N", "total number of evaluated reference-limit estimates with an available D-RL value for the method within the corresponding assessment scope (group or global).")
    )), "</li>",
    "<li><strong>d2 — Proximity</strong>", methodology_report_formula(d2_math, "d two equals one divided by one plus the mean absolute D R L."),
    methodology_report_where(c(
      methodology_report_variable_row("mean(|D<sub>RL</sub>|)", "arithmetic mean of the absolute D-RL values across all available LRL and URL estimates for the method within the corresponding assessment scope."),
      methodology_report_variable_row("|D<sub>RL</sub>|", "absolute reference limit deviation index, expressing the magnitude of the deviation from the comparative reference limit irrespective of direction.")
    )), "</li>",
    "<li><strong>d3 — Tail behaviour</strong>", methodology_report_formula(d3_math, "d three equals one divided by one plus the maximum of zero and the ninetieth percentile of absolute D R L minus one."),
    methodology_report_where(c(
      methodology_report_variable_row("P<sub>90</sub>(|D<sub>RL</sub>|)", "inclusive 90th percentile of the absolute D-RL values across the available LRL and URL estimates for the method within the corresponding assessment scope."),
      methodology_report_variable_row("max[0, P<sub>90</sub>(|D<sub>RL</sub>|) − 1]", "non-negative tail excess beyond the equivalence boundary; it equals zero when the 90th percentile is less than or equal to 1.")
    )), "</li>",
    "<li><strong>d4 — Severity</strong>", methodology_report_formula(d4_math, "d four equals one divided by one plus five times the number of absolute D R L values greater than two, divided by N."),
    methodology_report_where(c(
      methodology_report_variable_row("n(|D<sub>RL</sub>| &gt; 2)", "number of evaluated reference-limit estimates (LRLs and URLs) whose absolute deviation index is greater than 2."),
      methodology_report_variable_row("N", "total number of evaluated reference-limit estimates with an available D-RL value for the method within the corresponding assessment scope (group or global)."),
      methodology_report_variable_row("2", "severity threshold corresponding to a deviation greater than twice the permissible difference (pD)."),
      methodology_report_variable_row("5", "fixed multiplier that controls the strength of the penalty for severe deviations.")
    )), "</li>",
    "<li><strong>PRIDe Score — equally weighted geometric mean</strong>",
    methodology_report_formula(score_math, "PRIDe Score equals the fourth root of d one times d two times d three times d four.", TRUE),
    "</li></ul>"
  )
}

result_column_labels <- function(column_names) {
  labels <- c(
    Escopo = "Group",
    Posicao = "Position",
    Rank = "Rank",
    Metodo = "Method",
    N_limites = "N limits",
    Conformidade_n = "Conformity (n)",
    d1_Conformidade = "d1 — Conformity",
    Media_abs_D_RL = "Mean |D<sub>RL</sub>|",
    d2_Proximidade = "d2 — Proximity",
    P90_abs_D_RL = "P90 |D<sub>RL</sub>|",
    d3_Cauda = "d3 — Tail behaviour",
    Severidade_n = "Severity (n)",
    d4_Severidade = "d4 — Severity",
    PRIDE_RL_score = "PRIDE-RL score",
    Percentual_RLs_no_EI = "Limits within EI (%)",
    LRLs_no_EI = "LRLs within EI",
    Total_LRLs = "Total LRLs",
    URLs_no_EI = "URLs within EI",
    Total_URLs = "Total URLs",
    Total_no_EI = "Total within EI",
    Total_possivel = "Total possible",
    Registro = "Row",
    Analito = "Analyte",
    Unidade = "Unit",
    Decimais = "Decimal places",
    LRL_referencia = "Comparative LRL",
    URL_referencia = "Comparative URL",
    CVE = "CVE",
    pCVA = "pCVA",
    Medln = "Medln",
    pSDA_Med = "Median pSDA",
    Slope = "Slope",
    Intercept = "Intercept",
    pSDA_LRL = "pSDA LRL",
    pD_LRL = "pD LRL",
    pSDA_URL = "pSDA URL",
    pD_URL = "pD URL",
    EI_LRL_inferior = "Lower LRL EI",
    EI_LRL_superior = "Upper LRL EI",
    EI_URL_inferior = "Lower URL EI",
    EI_URL_superior = "Upper URL EI",
    EI_LRL = "LRL equivalence interval",
    EI_URL = "URL equivalence interval",
    LRL_estimado = "Estimated LRL",
    D_RL_LRL = "D<sub>RL</sub> LRL",
    Dentro_EI_LRL = "LRL within EI",
    URL_estimado = "Estimated URL",
    D_RL_URL = "D<sub>RL</sub> URL",
    Dentro_EI_URL = "URL within EI"
  )
  fallback <- gsub("_", " ", column_names, fixed = TRUE)
  matched <- unname(labels[column_names])
  matched[is.na(matched)] <- fallback[is.na(matched)]
  matched
}

format_result_df <- function(df, digits = 4L, percent_columns = character()) {
  out <- df
  integer_columns <- c(
    "Posicao", "Rank", "Registro", "n", "Decimais", "N_limites", "Conformidade_n", "Severidade_n",
    "LRLs_no_EI", "Total_LRLs", "URLs_no_EI", "Total_URLs", "Total_no_EI", "Total_possivel",
    "Dentro_EI_LRL", "Dentro_EI_URL"
  )

  for (nm in names(out)) {
    values <- out[[nm]]
    if (is.numeric(values)) {
      if (nm %in% percent_columns) {
        values <- ifelse(is.na(values), "", sprintf("%.2f%%", 100 * values))
      } else if (nm %in% integer_columns) {
        values <- ifelse(is.na(values), "", formatC(values, format = "f", digits = 0))
      } else {
        values <- ifelse(is.na(values), "", formatC(values, format = "f", digits = digits))
      }
    } else {
      values <- ifelse(is.na(values), "", as.character(values))
    }
    out[[nm]] <- html_escape(values)
  }
  names(out) <- result_column_labels(names(out))
  out
}

# Generic table builder used by Inclusion ranking, Equivalence intervals, and
# Detailed assessment in the Results tab.
build_kable_html <- function(df, caption = NULL, note = NULL, digits = 4L,
                             percent_columns = character(), max_rows = Inf,
                             scroll = TRUE) {
  if (is.null(df) || nrow(df) == 0L) return("<p class='empty'>No data available.</p>")

  shown <- head(df, max_rows)
  formatted <- format_result_df(shown, digits = digits, percent_columns = percent_columns)
  align <- paste0("l", paste(rep("c", max(0L, ncol(formatted) - 1L)), collapse = ""))

  table <- kableExtra::kbl(
    formatted,
    col.names = names(formatted),
    row.names = FALSE,
    align = align,
    caption = caption,
    escape = FALSE,
    format = "html",
    table.attr = "style='text-align:justify;line-height:1.65;color:#000000;font-size:1em;'"
  )
  table <- kableExtra::kable_styling(
    table,
    full_width = FALSE,
    position = "left",
    bootstrap_options = c("striped", "hover", "condensed", "responsive")
  )
  table <- kableExtra::row_spec(table, 0, bold = TRUE, color = "white", background = "#0d47a1")
  table <- kableExtra::column_spec(table, 1, bold = TRUE, color = "white", background = "#1976d2")

  if (ncol(formatted) > 0L && anyDuplicated(formatted[[1L]]) > 0L) {
    table <- kableExtra::collapse_rows(table, columns = 1, valign = "middle")
  }
  if (!is.null(note) && nzchar(note)) {
    table <- kableExtra::footnote(
      table,
      general_title = "<span class='table-note-title'>Note:</span> ",
      general = note,
      escape = FALSE,
      footnote_as_chunk = TRUE
    )
  }

  suffix <- if (nrow(df) > nrow(shown)) {
    sprintf("<p class='note'>Showing %d of %d rows.</p>", nrow(shown), nrow(df))
  } else {
    ""
  }
  table_html <- as.character(table)
  wrapper_class <- if (isTRUE(scroll)) "pride-kable-scroll" else "table-wrap"
  paste0("<div class='", wrapper_class, "'>", table_html, "</div>", suffix)
}

df_to_html <- function(df, digits = 4L, percent_columns = character(), note = NULL) {
  build_kable_html(
    df,
    note = note,
    digits = digits,
    percent_columns = percent_columns,
    scroll = FALSE
  )
}

format_composite_number <- function(x, digits = 3L) {
  ifelse(is.na(x) | !is.finite(x), "", formatC(x, format = "f", digits = digits))
}

pride_score_colors <- function(scores) {
  colors <- rep("#F5F5F5", length(scores))
  valid <- is.finite(scores)
  if (!any(valid)) return(colors)

  position <- pmin(1, pmax(0, (scores[valid] - 0.50) / 0.50))
  ramp <- grDevices::colorRamp(c("#FFF59D", "#DCE775", "#81C784"), space = "Lab")
  rgb <- ramp(position)
  colors[valid] <- grDevices::rgb(rgb[, 1L], rgb[, 2L], rgb[, 3L], maxColorValue = 255)
  colors
}

merge_composite_header_cells <- function(table, header_type = c("detailed", "ordered")) {
  header_type <- match.arg(header_type)
  table_html <- as.character(table)
  document <- xml2::read_html(paste0("<!doctype html><html><body>", table_html, "</body></html>"))
  table_node <- xml2::xml_find_first(document, ".//table")
  header_rows <- xml2::xml_find_all(table_node, "./thead/tr")
  if (length(header_rows) < 3L) return(table_html)

  grouped_row <- header_rows[[length(header_rows) - 1L]]
  detail_row <- header_rows[[length(header_rows)]]
  grouped_cells <- xml2::xml_find_all(grouped_row, "./th")
  detail_cells <- xml2::xml_find_all(detail_row, "./th")

  if (header_type == "detailed") {
    if (length(grouped_cells) < 5L || length(detail_cells) < 5L) return(table_html)
    grouped_indices <- c(seq_len(4L), length(grouped_cells))
    detail_indices <- c(seq_len(4L), length(detail_cells))
  } else {
    if (length(grouped_cells) < 1L || length(detail_cells) < 1L) return(table_html)
    grouped_indices <- 1L
    detail_indices <- 1L
  }

  cells_to_merge <- grouped_cells[grouped_indices]
  xml2::xml_set_attr(cells_to_merge, "rowspan", "2")
  current_style <- xml2::xml_attr(cells_to_merge, "style")
  current_style[is.na(current_style)] <- ""
  xml2::xml_set_attr(
    cells_to_merge,
    "style",
    paste0(current_style, ";vertical-align:middle!important;")
  )
  xml2::xml_remove(detail_cells[detail_indices])
  as.character(table_node)
}

wrap_composite_kable <- function(table, scroll = TRUE, header_type = c("detailed", "ordered")) {
  header_type <- match.arg(header_type)
  wrapper_class <- if (isTRUE(scroll)) "pride-kable-scroll composite-table-block" else "table-wrap composite-table-block"
  table_html <- merge_composite_header_cells(table, header_type = header_type)
  paste0("<div class='", wrapper_class, "'>", table_html, "</div>")
}

build_composite_scope_table <- function(df, methods, scope, scroll = TRUE) {
  current <- df[df$Escopo == scope, , drop = FALSE]
  if (nrow(current) == 0L) return("")

  current$Idx <- match(current$Metodo, methods$label)
  current <- current[order(current$Idx, current$Metodo), , drop = FALSE]
  display <- data.frame(
    Rank = format_composite_number(current$Rank, 0L),
    Method = html_escape(current$Metodo),
    Idx = format_composite_number(current$Idx, 0L),
    N_limits = format_composite_number(current$N_limites, 0L),
    Conformity_n = format_composite_number(current$Conformidade_n, 0L),
    d1 = format_composite_number(current$d1_Conformidade, 3L),
    Mean_abs_D_RL = format_composite_number(current$Media_abs_D_RL, 2L),
    d2 = format_composite_number(current$d2_Proximidade, 3L),
    P90_abs_D_RL = format_composite_number(current$P90_abs_D_RL, 2L),
    d3 = format_composite_number(current$d3_Cauda, 3L),
    Severity_n = format_composite_number(current$Severidade_n, 0L),
    d4 = format_composite_number(current$d4_Severidade, 3L),
    PRIDE_RL_score = format_composite_number(current$PRIDE_RL_score, 3L),
    stringsAsFactors = FALSE,
    check.names = FALSE
  )

  column_labels <- c(
    "", "", "", "",
    "n(|D<sub>RL</sub>| ≤ 1) / N", "d1",
    "mean(|D<sub>RL</sub>|)", "d2",
    "P90(|D<sub>RL</sub>|)", "d3",
    "n(|D<sub>RL</sub>| &gt; 2)", "d4", ""
  )
  dimension_header <- c(
    Rank = 1, Method = 1, Idx = 1, `N limits` = 1,
    Conformity = 2, Proximity = 2, `Tail behaviour` = 2,
    Severity = 2, `PRIDE-RL score` = 1
  )
  scope_title <- if (identical(scope, "Global")) {
    groups <- setdiff(unique(as.character(df$Escopo)), "Global")
    if (length(groups) > 0L) {
      paste0("Global: all reference limits (", paste(groups, collapse = " + "), ")")
    } else {
      "Global: all reference limits"
    }
  } else {
    scope
  }

  table <- kableExtra::kbl(
    display,
    col.names = column_labels,
    row.names = FALSE,
    align = "clccccccccccc",
    escape = FALSE,
    format = "html",
    table.attr = "class='pride-composite-table' style='text-align:center;line-height:1.45;color:#000000;font-size:1em;'"
  )
  table <- kableExtra::kable_styling(
    table,
    full_width = FALSE,
    position = "left",
    bootstrap_options = c("hover", "condensed", "responsive")
  )
  table <- kableExtra::row_spec(table, 0, bold = TRUE, color = "white", background = "#203D6B")
  table <- kableExtra::add_header_above(
    table,
    header = dimension_header,
    bold = TRUE,
    color = "white",
    background = "#203D6B",
    escape = FALSE,
    line_sep = FALSE
  )
  table <- kableExtra::add_header_above(
    table,
    header = stats::setNames(ncol(display), html_escape(scope_title)),
    bold = TRUE,
    color = "white",
    background = "#333333",
    escape = FALSE,
    line_sep = FALSE
  )
  table <- kableExtra::row_spec(table, seq_len(nrow(display)), background = "#FFFEEF")
  table <- kableExtra::column_spec(table, 1, bold = TRUE, background = "#F2F2F2")
  table <- kableExtra::column_spec(table, 2, bold = TRUE)
  table <- kableExtra::column_spec(
    table,
    ncol(display),
    bold = TRUE,
    color = "#000000",
    background = pride_score_colors(current$PRIDE_RL_score)
  )
  wrap_composite_kable(table, scroll = scroll, header_type = "detailed")
}

build_ordered_ranking_table <- function(df, scroll = TRUE) {
  scopes <- unique(as.character(df$Escopo))
  scopes <- scopes[!is.na(scopes) & nzchar(scopes)]
  if (length(scopes) == 0L) return("")

  scope_rows <- lapply(scopes, function(scope) {
    current <- df[df$Escopo == scope, , drop = FALSE]
    current[order(current$Posicao, current$Rank, -current$PRIDE_RL_score), , drop = FALSE]
  })
  maximum <- max(vapply(scope_rows, nrow, integer(1)))
  display <- data.frame(Pos = as.character(seq_len(maximum)), stringsAsFactors = FALSE)
  column_labels <- ""
  score_columns <- integer()
  score_values <- list()
  method_columns <- integer()
  rank_columns <- integer()

  for (i in seq_along(scopes)) {
    current <- scope_rows[[i]]
    missing_rows <- maximum - nrow(current)
    pad_character <- function(values) c(values, rep("", missing_rows))
    pad_numeric <- function(values) c(values, rep(NA_real_, missing_rows))

    display[[paste0("rank_", i)]] <- pad_character(format_composite_number(current$Rank, 0L))
    display[[paste0("method_", i)]] <- pad_character(html_escape(current$Metodo))
    display[[paste0("score_", i)]] <- pad_character(format_composite_number(current$PRIDE_RL_score, 3L))
    column_labels <- c(column_labels, "Rank", "Method", "PRIDE-RL score")
    rank_columns <- c(rank_columns, ncol(display) - 2L)
    method_columns <- c(method_columns, ncol(display) - 1L)
    score_columns <- c(score_columns, ncol(display))
    score_values[[i]] <- pad_numeric(current$PRIDE_RL_score)
  }

  group_header <- stats::setNames(1, "Pos.")
  for (scope in scopes) {
    group_header <- c(group_header, stats::setNames(3, html_escape(scope)))
  }

  table <- kableExtra::kbl(
    display,
    col.names = column_labels,
    row.names = FALSE,
    align = paste0("c", paste(rep("c", ncol(display) - 1L), collapse = "")),
    escape = FALSE,
    format = "html",
    table.attr = "class='pride-ordered-table' style='text-align:center;line-height:1.45;color:#000000;font-size:1em;'"
  )
  table <- kableExtra::kable_styling(
    table,
    full_width = FALSE,
    position = "left",
    bootstrap_options = c("hover", "condensed", "responsive")
  )
  table <- kableExtra::row_spec(table, 0, bold = TRUE, color = "white", background = "#203D6B")
  table <- kableExtra::add_header_above(
    table,
    header = group_header,
    bold = TRUE,
    color = "white",
    background = "#203D6B",
    escape = FALSE,
    line_sep = FALSE
  )
  table <- kableExtra::add_header_above(
    table,
    header = c(`Ordered ranking` = ncol(display)),
    bold = TRUE,
    color = "white",
    background = "#333333",
    escape = FALSE,
    line_sep = FALSE
  )
  table <- kableExtra::row_spec(table, seq_len(nrow(display)), background = "#FFFEEF")
  table <- kableExtra::column_spec(table, 1, bold = TRUE, background = "#F2F2F2")
  for (column in c(rank_columns, method_columns)) {
    table <- kableExtra::column_spec(table, column, bold = TRUE)
  }
  for (i in seq_along(score_columns)) {
    table <- kableExtra::column_spec(
      table,
      score_columns[i],
      bold = TRUE,
      color = "#000000",
      background = pride_score_colors(score_values[[i]])
    )
  }
  wrap_composite_kable(table, scroll = scroll, header_type = "ordered")
}

# Assemble the group-specific and Global tables displayed in Results >
# Composite ranking.
build_composite_tables_html <- function(df, methods, scroll = TRUE) {
  if (is.null(df) || nrow(df) == 0L) return("<p class='empty'>No data available.</p>")
  scopes <- unique(as.character(df$Escopo))
  scopes <- scopes[!is.na(scopes) & nzchar(scopes)]
  detailed <- vapply(
    scopes,
    function(scope) build_composite_scope_table(df, methods, scope, scroll = scroll),
    character(1)
  )
  note <- paste0(
    "<div class='composite-note'><span class='table-note-title'>Note:</span> ",
    "d1–d4 are the normalized dimensions. The PRIDE-RL score is the geometric mean ",
    "(d1 × d2 × d3 × d4)<sup>1/4</sup>; the color changes from yellow to green as the score increases.</div>"
  )
  paste0(
    "<div class='composite-table-stack'>",
    paste0(detailed, collapse = ""),
    build_ordered_ranking_table(df, scroll = scroll),
    note,
    "</div>"
  )
}

# =============================================================================
# 07. SELF-CONTAINED HTML REPORT GENERATION
# =============================================================================
# Screen link: "Download HTML Report" in the Data entry command panel.
# These helpers embed the heatmap and logo, reproduce all metadata and inputs,
# render every analytical table, add references, and build responsive lateral
# navigation for desktop, iPhone, iPad, Android phones, and Android tablets.

base64_encode_raw <- function(bytes) {
  alphabet <- strsplit("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/", "", fixed = TRUE)[[1]]
  n <- length(bytes)
  if (n == 0L) return("")
  ints <- as.integer(bytes)
  out <- character(4L * ceiling(n / 3L))
  oi <- 1L
  for (i in seq.int(1L, n, by = 3L)) {
    remaining <- n - i + 1L
    b1 <- ints[i]
    b2 <- if (remaining >= 2L) ints[i + 1L] else 0L
    b3 <- if (remaining >= 3L) ints[i + 2L] else 0L
    triple <- b1 * 65536 + b2 * 256 + b3
    out[oi] <- alphabet[floor(triple / 262144) + 1L]
    out[oi + 1L] <- alphabet[floor(triple %% 262144 / 4096) + 1L]
    out[oi + 2L] <- if (remaining >= 2L) alphabet[floor(triple %% 4096 / 64) + 1L] else "="
    out[oi + 3L] <- if (remaining >= 3L) alphabet[triple %% 64 + 1L] else "="
    oi <- oi + 4L
  }
  paste0(out, collapse = "")
}

base64_encode_file <- function(path) {
  size <- file.info(path)$size
  con <- file(path, open = "rb")
  on.exit(close(con), add = TRUE)
  base64_encode_raw(readBin(con, what = "raw", n = size))
}

metadata_report_html <- function(metadata) {
  labels <- c(
    specialist = "Specialist responsible for data analysis",
    data_source = "Data Source",
    measurement_procedure = "Measurement Procedure and Analytical Method",
    sample_type = "Sample Type",
    age_range = "Age Range",
    comparative_reference_source = "Source of the Comparative Reference"
  )
  rows <- vapply(names(labels), function(key) {
    value <- trimws(as.character(metadata[[key]] %||% ""))
    if (!nzchar(value)) value <- "Not provided."
    value <- gsub("\n", "<br>", html_escape(value), fixed = TRUE)
    paste0(
      "<div class='analysis-field'><dt>", html_escape(labels[[key]]), "</dt><dd>",
      value, "</dd></div>"
    )
  }, character(1))
  paste0("<dl class='analysis-info'>", paste0(rows, collapse = ""), "</dl>")
}

report_configuration_html <- function(methods, group_names) {
  group_labels <- trimws(as.character(unname(group_names)))
  group_labels[!nzchar(group_labels)] <- "Unnamed group"
  method_labels <- trimws(as.character(methods$label))
  method_labels[!nzchar(method_labels)] <- "Unnamed method"

  group_items <- paste0("<li>", html_escape(group_labels), "</li>", collapse = "")
  method_items <- paste0("<li>", html_escape(method_labels), "</li>", collapse = "")
  paste0(
    "<div class='configuration-grid'>",
    "<article class='configuration-card'><h3>Assessment groups</h3><ol>", group_items, "</ol></article>",
    "<article class='configuration-card'><h3>Compared methods</h3><ol>", method_items, "</ol></article>",
    "</div>"
  )
}

input_data_report_html <- function(groups, group_names, methods) {
  group_blocks <- vapply(names(groups), function(group_id) {
    label <- trimws(as.character(group_names[[group_id]] %||% group_id))
    if (!nzchar(label)) label <- "Unnamed group"
    df <- groups[[group_id]]
    expected <- c(BASE_COLUMNS, method_columns(methods))
    for (column in setdiff(expected, names(df))) df[[column]] <- NA_real_
    df <- df[, expected, drop = FALSE]
    keep <- nonempty_rows(df, methods)
    df <- df[keep, , drop = FALSE]

    if (nrow(df) == 0L) {
      return(paste0(
        "<article class='input-group-card'><h3>", html_escape(label), "</h3>",
        "<p class='empty'>No analyte data were provided for this group.</p></article>"
      ))
    }

    names(df) <- c(
      BASE_COLUMNS,
      unlist(lapply(methods$label, function(method_label) {
        html_escape(c(paste(method_label, "LRL"), paste(method_label, "URL")))
      }), use.names = FALSE)
    )
    paste0(
      "<article class='input-group-card'><h3>", html_escape(label), "</h3>",
      build_kable_html(
        df,
        digits = 6L,
        note = "Values reproduced from the data-entry table used for this analysis.",
        scroll = FALSE
      ),
      "</article>"
    )
  }, character(1))

  paste0("<div class='input-groups'>", paste0(group_blocks, collapse = ""), "</div>")
}

coverage_report_note <- function(coverage, z_value) {
  coverage_label <- format_coverage_percent(coverage)
  proposal <- if (abs(as.numeric(coverage) - 0.80) < 1e-9) {
    "the original proposal of Haeckel et al. (2016)"
  } else {
    "the criterion proposed by Dias et al. (2027) in the paper describing the LabRI method"
  }
  one_sided <- 100 * stats::pnorm(as.numeric(z_value))
  paste0(
    "The equivalence interval is calculated separately around each comparative LRL and URL and defines the range within which a difference is considered not clinically relevant under the method's permissible-uncertainty criterion. Its width is based on the permissible analytical standard deviation at that RL, derived from the empirical coefficient of variation estimated from the comparative reference interval specified for each analyte. The selected ",
    coverage_label, " nominal central coverage uses <i>z</i> = ", sprintf("%.5f", z_value),
    ", corresponding to the ", formatC(one_sided, format = "f", digits = 0),
    "th one-sided standard-normal percentile and ", proposal, "."
  )
}

# Build the complete portable report as one HTML file. No external stylesheet,
# script, logo, or heatmap file is required when the report is opened.
write_report_html <- function(path, result, methods, metadata, groups, group_names, heatmap_path) {
  image_data <- base64_encode_file(heatmap_path)
  generated <- format(Sys.time(), "%Y-%m-%d %H:%M:%S %Z")
  configuration_html <- report_configuration_html(methods, group_names)
  input_html <- input_data_report_html(groups, group_names, methods)
  coverage_note <- coverage_report_note(result$coverage, result$z_value)
  html <- paste0(
    "<!doctype html><html lang='en'><head><meta charset='utf-8'>",
