  .btn-report-download { color:#fff!important; background:#6f42a6!important; border-color:#593486!important; }
  .btn-report-download:hover,.btn-report-download:focus { background:#593486!important; border-color:#47296d!important; }
  .btn-report-disabled { cursor:not-allowed; opacity:.48; pointer-events:none; }
  .pride-result-table { margin-top:14px; padding:16px; overflow:hidden; background:#fff; border:1px solid #dce6e8; border-radius:7px; box-shadow:0 2px 8px rgba(31,55,64,.05); }
  .pride-kable-scroll { width:100%; overflow-x:auto; padding-bottom:4px; }
