  .pride-result-table table caption { caption-side:top; padding:0 0 12px; color:#0d47a1; font-size:17px; font-weight:700; text-align:left; }
  .pride-result-table th { padding:10px 11px !important; border:1px solid #d3dee2 !important; vertical-align:middle !important; text-align:center !important; white-space:normal; line-height:1.25; }
  .pride-result-table td { padding:8px 11px !important; border:1px solid #dbe4e7 !important; vertical-align:middle !important; white-space:nowrap; }
