  .composite-table-block td { text-align:center !important; vertical-align:middle !important; }
  .composite-table-block tbody tr:hover td { filter:brightness(.97); }
  .composite-note { margin:0 0 8px; padding:11px 14px; background:#f3f6f8; border-left:4px solid #203D6B; color:#263238; font-size:12px; line-height:1.5; }
