  .entry-paste-guide kbd { padding:2px 6px; background:#fff; border:1px solid #b9c7ca; border-bottom-width:2px; border-radius:3px; color:#334b52; box-shadow:none; font-family:inherit; font-size:11px; }
  .entry-table-scroll { width:100%; max-height:570px; overflow:auto; position:relative; scrollbar-color:#83979d #edf1f2; scrollbar-width:thin; }
