  .entry-delete:hover, .entry-delete:focus { background:#fae9e8; border-color:#e5b9b5; color:#a32b25; outline:0; }
  .entry-table-footer { min-height:42px; display:flex; justify-content:space-between; align-items:center; gap:16px; padding:9px 13px; background:#f5f8f8; color:#5f747b; border-top:1px solid #d5dfe1; font-size:12px; }
  .entry-table-footer .fa, .entry-table-footer .fas { margin-right:6px; }
