  .nav-tabs>li>a { color:#0033CC; background:#FFFEC2; border-color:#e5e3a1; font-weight:600; }
  .nav-tabs>li>a:hover, .nav-tabs>li>a:focus { color:#062d79; background:#fff9a8; border-color:#d8d58b; }
  .nav-tabs>li.active>a, .nav-tabs>li.active>a:hover, .nav-tabs>li.active>a:focus { color:#fff; background:#0d47a1; border-color:#0d47a1; }
  .pride-app-footer { margin-top:32px; color:#fff; background:linear-gradient(180deg,#416fc9 0%,#062d79 100%); border-top:1px solid #d6dfec; }
  .pride-app-footer-inner { display:flex; align-items:center; justify-content:center; flex-direction:column; gap:10px; min-height:116px; padding:18px 24px 20px; text-align:center; }
  .pride-app-footer-copy { margin:0; color:#fff; font-size:14px; line-height:1.55; }
  .pride-app-footer-links { display:flex; align-items:stretch; justify-content:center; flex-wrap:wrap; gap:12px; }
  .pride-app-footer-link { display:inline-flex; align-items:center; justify-content:center; flex-direction:column; gap:4px; min-width:132px; min-height:58px; padding:7px 14px; color:#fff!important; text-decoration:none!important; border:1px solid rgba(255,255,255,.24); border-radius:3px; background:rgba(6,45,121,.22); transition:background-color .18s ease,border-color .18s ease; }
  .pride-app-footer-link:hover, .pride-app-footer-link:focus { color:#fff!important; background:rgba(6,45,121,.48); border-color:rgba(255,255,255,.58); outline:0; }
  .pride-app-footer-link:focus-visible { box-shadow:0 0 0 3px rgba(255,254,194,.72); }
  .pride-app-footer-icon { font-size:24px; line-height:1; }
