# =============================================================================
# 11. SHINY USER INTERFACE DEFINITION
# =============================================================================
# The UI is organized in the same order as the navigation bar. Each SCREEN
# marker below identifies the code responsible for a visible Shiny tab.

# Shared footer displayed below the navbarPage content on every screen.
app_footer <- tags$footer(
  class = "pride-app-footer",
  role = "contentinfo",
  tags$div(
    class = "pride-app-footer-inner",
    tags$p(
      class = "pride-app-footer-copy",
      "Developed by Alan Carvalho Dias | Powered by LabR Group | License: GPL-3.0 | Code available at:"
    ),
    tags$div(
      class = "pride-app-footer-links",
      tags$a(
        class = "pride-app-footer-link",
        href = "https://github.com/labrgrupo/PRIDe-RL_shiny",
        target = "_blank",
        rel = "noopener noreferrer",
        `aria-label` = "GitHub — opens in a new tab",
        icon("github", class = "pride-app-footer-icon"),
        tags$span(class = "pride-app-footer-label", "GitHub")
      ),
      tags$a(
        class = "pride-app-footer-link",
        href = "https://grupolabr.com/LabRI_Packed",
        target = "_blank",
        rel = "noopener noreferrer",
        `aria-label` = "Lab R Group Website — opens in a new tab",
        icon("globe", class = "pride-app-footer-icon"),
        tags$span(class = "pride-app-footer-label", "Lab R Group Website")
      )
    )
  )
)

# Application shell: Base64 logo, title, subtitle, navigation, shared CSS, and
# the JavaScript used by the editable input table.
ui <- navbarPage(
  title = tags$div(
    class = "pride-brand-content",
    tags$img(
      class = "pride-brand-logo",
      src = PRIDE_LOGO_DATA_URI,
      alt = "PRIDe-RL logo",
      width = "168",
      height = "184"
    ),
    tags$div(
      class = "pride-brand-copy",
      tags$h1(
        class = "pride-brand-title",
        "Performance Ranking by Index of Deviation of Reference Limits (PRIDe-RL)"
      ),
      tags$p(
        class = "pride-brand-subtitle",
        "A multidimensional framework for comparative evaluation and ranking of reference-limit estimation methods"
      )
    )
  ),
  id = "main_nav",
  header = tags$head(tags$style(HTML(app_css)), tags$script(HTML(entry_table_js))),
  # SCREEN 1 — DATA ENTRY
  # Analysis metadata, nominal coverage, assessment groups, compared methods,
  # main commands, and the editable analyte/limit grid.
  tabPanel(
    "Data entry",
    fluidPage(
      br(),
      tags$div(
        class = "row setup-row pride-setup-grid",
        column(
          width = 3,
          div(
            class = "setup-card analysis-card",
            h4("Analysis information"),
            p(class = "setup-description", "Document the datasets, populations, procedures, and comparative reference sources included in this multi-analyte assessment."),
            textInput("analysis_specialist", "Specialist responsible for data analysis", "", width = "100%"),
            p(class = "field-note", tags$strong("Note 1: "), "Provide the name of the person or people responsible for the data-processing and analysis workflow."),
            textAreaInput("data_source", "Data Source", "", rows = 2, width = "100%"),
            p(class = "field-note", tags$strong("Note 2: "), "Identify where the datasets for all assessment groups were obtained. If sources differ, associate each source with the corresponding group or dataset."),
            textAreaInput("measurement_procedure", "Measurement Procedure and Analytical Method", "", rows = 3, width = "100%"),
            p(class = "field-note", tags$strong("Note 3: "), "Describe the measurement procedure(s) and analytical method(s) used. When several procedures apply, identify the related analytes/tests, assessment groups, or compared methods."),
            textAreaInput("sample_type", "Sample Type", "", rows = 2, width = "100%"),
            p(class = "field-note", tags$strong("Note 4: "), "Describe the sample type or types, such as whole blood, serum, plasma, 24-hour urine, or random urine. Link differing sample types to the relevant analytes/tests or groups."),
            textAreaInput("age_range", "Age Range", "", rows = 2, width = "100%"),
            p(class = "field-note", tags$strong("Note 5: "), "Report the age range concisely. If ranges differ among groups or analytes/tests, identify each applicable range. Examples: '7 to 16 years', 'under 2 years', '7–16 years', or '< 2 years'."),
            textAreaInput("comparative_reference_source", "Source of the Comparative Reference", "", rows = 3, width = "100%"),
            div(
              class = "field-note field-note-expanded",
              p(
                tags$strong("NOTE 6: "),
                "To perform reference interval verification, a comparative reference interval must be provided. This comparative reference interval can be selected from various sources, such as:"
              ),
              tags$ul(
                tags$li(tags$strong("Reagent Kit Package Inserts: "), "Specified reference ranges for laboratory tests based on manufacturer's validation studies."),
                tags$li(tags$strong("Scientific publications and guidelines from specialized organizations: "), "Intervals derived from multicenter studies and reviews that reflect widely accepted practices in the field."),
                tags$li(tags$strong("Academic Books (Textbooks): "), "Consolidated and widely accepted reference intervals based on extensive scientific literature and available in academic books."),
                tags$li(tags$strong("Local or multicentric studies: "), "Results obtained for a specific population or harmonized across multiple regions."),
                tags$li(tags$strong("Indirect methods: "), "Involve previous studies that estimated reference intervals using patient data stored in laboratory information systems (LIS), applying algorithms to identify and exclude potentially pathological values.")
              )
            ),
            selectInput(
              "coverage",
              "Nominal central coverage of the equivalence interval",
              choices = c("80%" = "0.80", "90%" = "0.90"),
              selected = "0.90"
            ),
            uiOutput("coverage_helper")
          )
        ),
        column(
          width = 4,
          div(
            class = "setup-card",
            h4("Assessment groups"),
            p(class = "setup-description", "View and edit all groups. Select the group whose data will be entered."),
            uiOutput("group_selector_ui"),
            uiOutput("group_editor_ui"),
            div(
              class = "group-actions",
              actionButton("save_group_names", "Apply group names", class = "btn-primary", width = "100%"),
              actionButton("add_group", "Add new group", icon = icon("plus"), width = "100%"),
              uiOutput("group_remove_ui"),
              actionButton("remove_group", "Remove selected group", icon = icon("trash"), class = "btn-danger", width = "100%")
            )
          )
        ),
        column(
          width = 5,
          div(
            class = "setup-card",
            h4("Compared methods"),
            p(class = "setup-description", "Edit names directly. Entered limits remain linked to the correct method."),
            uiOutput("method_editor_ui"),
            div(
              class = "method-actions",
              actionButton("save_method_names", "Apply method names", class = "btn-primary", width = "100%"),
              actionButton("add_method", "Add new method", width = "100%"),
              uiOutput("method_remove_ui"),
              actionButton("remove_method", "Remove selected method", class = "btn-danger", width = "100%")
            )
          )
        )
      ),
      div(
        class = "command-panel",
        div(
          class = "command-panel-title",
          h3("Main commands"),
          p("Save or reset the current configuration, run the analysis, and obtain the HTML report.")
        ),
        div(
          class = "command-buttons",
          actionButton("save_configuration", "Save Configuration", icon = icon("save"), class = "btn-save-config"),
          actionButton("clear_configuration", "Clear Configuration", icon = icon("eraser"), class = "btn-clear-config"),
          actionButton("calculate", "Generate Analysis", icon = icon("play"), class = "btn-generate-analysis"),
          uiOutput("report_download_ui", inline = TRUE)
        )
      ),
      div(
        class = "entry-section-head",
        div(
